const meta = $('Get Meta').first().json;
const sh = (meta.sheets||[]).find(s => s.properties && s.properties.title === 'Leads');
if (!sh) throw new Error('Leads tab missing');
const gid = sh.properties.sheetId;
const rows = ($('Get Values').first().json.values) || [];
if (!rows.length) throw new Error('no rows');
const header = rows[0].map(h => String(h).trim());
const ORDER = ['Timestamp','First Name','Last Name','Phone','Email','Status','Lead Type','Price Range','Timeline','Financing','Line Type','Searched Address','Source','Campaign','Ad','Message','Notes','Last Touch','On Mailer List','MailerLite Synced','Day 5 Email Sent','Already In Database','Meta Lead ID'];
const missing = ORDER.filter(n => n !== 'Line Type' && header.indexOf(n) === -1);
if (missing.length) throw new Error('headers not found: ' + missing.join(', '));
const extra = header.filter(h => h && ORDER.indexOf(h) === -1);
if (extra.length) throw new Error('unmapped existing headers: ' + extra.join(', '));
const idx = ORDER.map(n => header.indexOf(n));
const out = rows.map(function(r, i){
  return ORDER.map(function(n, j){
    const k = idx[j];
    if (k === -1) return i === 0 ? n : '';
    const v = r[k];
    return (v === undefined || v === null) ? '' : v;
  });
});
const STOPS = ['Replied','Called - No Answer','Left Voicemail','Appointment Set','Won','Lost','Dead','Do Not Contact','Unsubscribed','Bounced','Spam Complaint'];
const clearOld = { setDataValidation: { range: { sheetId: gid, startRowIndex: 1, endRowIndex: 2000, startColumnIndex: 16, endColumnIndex: 17 } } };
const rule = { condition: { type: 'ONE_OF_LIST', values: STOPS.map(function(v){ return { userEnteredValue: v }; }) }, showCustomUi: true, strict: false };
const setNew = { setDataValidation: { range: { sheetId: gid, startRowIndex: 1, endRowIndex: 2000, startColumnIndex: 5, endColumnIndex: 6 }, rule: rule } };
const backup = JSON.stringify({ requests: [ { duplicateSheet: { sourceSheetId: gid, newSheetName: 'Leads BACKUP 0804' } } ] });
const values = JSON.stringify({ values: out });
const validation = JSON.stringify({ requests: [ clearOld, setNew ] });
const range = 'Leads!A1:W' + out.length;
return [{ json: { range: range, gid: gid, rowCount: out.length, colCount: ORDER.length, oldHeader: header, newHeader: ORDER, backup: backup, values: values, validation: validation } }];
